*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#f5f2ea;font-synthesis:none;text-rendering:optimizeLegibility;--cream:#f3efe4;--muted:rgba(245,242,234,.59);--line:rgba(255,255,255,.17);--gold:#e4c391} html,body,#game{height:100%;width:100%;margin:0;overflow:hidden;background:#101a22} body{overscroll-behavior:none} button,input{font:inherit} button{color:inherit} #game{position:relative;isolation:isolate} #world{position:absolute;inset:0;width:100%;height:100%;display:block;z-index:-3} .vignette{position:absolute;inset:0;z-index:-2;pointer-events:none;background:linear-gradient(180deg,rgba(11,19,25,.5) 0%,transparent 23%,transparent 54%,rgba(13,20,25,.21) 70%,rgba(13,19,23,.85) 100%),linear-gradient(90deg,rgba(15,21,24,.14),transparent 42%,transparent 72%,rgba(15,21,24,.22))}.topbar{position:absolute;top:0;left:0;right:0;height:86px;padding:24px 4.3vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.12);background:linear-gradient(180deg,rgba(12,21,27,.29),transparent)}.brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:var(--cream);font:700 12px Manrope,sans-serif;letter-spacing:.18em}.brand small{display:block;color:rgba(255,255,255,.53);font:500 8px 'DM Mono',monospace;letter-spacing:.17em;margin-top:4px}.brand-mark{width:31px;height:31px;border:1px solid rgba(255,255,255,.62);display:grid;place-items:center;font:500 20px Georgia,serif;letter-spacing:-.08em;transform:rotate(-7deg);color:#f4dfbc}.world-label{display:flex;align-items:center;gap:12px;color:rgba(255,255,255,.79);font:10px 'DM Mono',monospace;letter-spacing:.14em}.world-label i{height:14px;width:1px;background:rgba(255,255,255,.25)}.live-dot{height:5px;width:5px;border-radius:50%;background:#c9e2b4;box-shadow:0 0 11px #d1eabc}.icon-button{width:34px;height:34px;border:1px solid var(--line);background:rgba(255,255,255,.045);border-radius:50%;cursor:pointer;color:rgba(255,255,255,.7)}.coordinates{position:a