ing:.13em}.controls-hint b{font-weight:400;color:rgba(255,255,255,.4);padding:0 6px}.key{display:inline-grid;place-items:center;width:18px;height:18px;border:1px solid rgba(255,255,255,.42);background:rgba(16,25,28,.25);font:9px 'DM Mono',monospace;color:#fff}.key-stack{display:grid;grid-template-columns:repeat(3,18px);gap:2px}.key-stack .key:first-child{grid-column:2}.key-stack .key:nth-child(2){grid-column:1}.key-stack .key:nth-child(3){grid-column:2}.key-wide{width:auto;padding:0 7px}.command{height:59px;width:min(760px,85vw);position:relative;display:flex;align-items:center;border:1px solid rgba(255,255,255,.52);background:rgba(17,26,29,.78);box-shadow:0 12px 50px rgba(0,0,0,.2);backdrop-filter:blur(15px)}.command:focus-within{border-color:rgba(239,213,174,.9);box-shadow:0 0 0 1px rgba(239,213,174,.18),0 12px 50px rgba(0,0,0,.25)}.command-symbol{font-size:21px;color:#ddc39d;margin:0 17px}.command input{flex:1;min-width:0;border:0;outline:0;background:transparent;color:#fffaf0;font:400 15px Manrope,sans-serif;letter-spacing:-.015em}.command input::placeholder{color:rgba(255,255,255,.56)}.input-note{position:absolute;right:148px;top:8px;color:rgba(255,255,255,.36);font:7px 'DM Mono',monospace;letter-spacing:.13em;pointer-events:none}.command button{align-self:stretch;margin:6px;padding:0 16px;border:0;background:#e3c49a;color:#202720;display:flex;align-items:center;gap:15px;cursor:pointer;font:700 9px 'DM Mono',monospace;letter-spacing:.1em;transition:background .2s}.command button:hover{background:#f1d8b2}.command button i{font:16px sans-serif;font-style:normal}.bottom-note{display:flex;align-items:center;gap:8px;margin-top:14px;color:rgba(255,255,255,.51);font:8px 'DM Mono',monospace;letter-spacing:.15em}.bottom-note>span:first-child{color:#e3c49a}.bottom-sep{color:rgba(255,255,255,.28)}.bottom-note button{border:0;background:transparent;color:rgba(255,255,255,.71);font:inherit;letter-spacing:inherit;padding:0 0 0 7px;cursor:pointer}.bottom-note button:hover{color:#f1d8b2}.toast{position:absolute;top:96px;left:50%;transform:translate(-50%,-10px);padding:10px 17px;background:rgba(18,28,30,.8);border:1px solid rgba(255,255,255,.19);backdrop-filter:blur(8px);font:10px 'DM Mono',monospace;letter-spacing:.1em;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.loading{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;background:#293b3f;color:rgba(255,255,255,.77);font:9px 'DM Mono',monospace;letter-spacing:.2em;transition:opacity .8s}.loading.done{opacity:0;pointer-events:none}.loading-mark{font:italic 48px Georgia,serif;color:#e4c391;animation:breathe 1.4s infinite alternate}@keyframes breathe{to{opacity:.42;transform:scale(.94)}}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.mobile-controls{display:none}
