function colorFrom(text){for(const [name,color] of Object.entries(palette))if(text.includes(name))return color;return ['#d3a87a','#9ba982','#819ea0','#bb9075','#ada1bb'][Math.floor(rand()*5)];}
function setTime(kind){
  timeState=kind;
